        {"query": "zero trust identity verification", "relevant": {"doc-security-2021", "doc-security-2023"}},
        {"query": "reranking and MMR improve retrieval", "relevant": {"doc-ml-2024", "doc-ml-2022"}},
        {"query": "vector database similarity search", "relevant": {"doc-db-2020"}},
        {"query": "production monitoring of rag systems", "relevant": {"doc-ops-2023"}},
        {"query": "identity access", "relevant": {"doc-security-2021", "doc-security-2023"},
         "filters": {"category": "security"}},
        {"query": "how to filter by metadata before ranking", "relevant": {"doc-ml-2024"},
         "filters": {"tags": {"$has": "filtering"}}},
    ]
    metrics = evaluate(rag, cases)
    print(json.dumps(metrics, indent=2))

    # Persistence round-trip check
    rag.save_index("metadata_rag_index.json")
    clone = MetadataRAG()
    clone.load_index("metadata_rag_index.json")
    assert clone.statistics["chunks"] == rag.statistics["chunks"], "index reload mismatch"
    a = rag.query("hybrid retrieval")
    b = clone.query("hybrid retrieval")
    assert [h.chunk.chunk_id for h in a["results"]] == [
        h.chunk.chunk_id for h in b["results"]
    ], "index reload changed results"
    print("\nIndex persistence round-trip: OK "
          f"({clone.statistics['chunks']} chunks reloaded)")


def main(argv: Optional[list[str]] = None) -> int:
    parser = argparse.ArgumentParser(description="Metadata-aware RAG system")
    parser.add_argument("--demo", action="store_true", default=True,
                        help="run the demo (default)")
    args = parser.parse_args(argv)
    if args.demo:
        run_demo()
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
Metadata-aware RAG system: metadata filtering + relevance ranking.

A self-contained implementation (Python stdlib only) covering the full RAG
pipeline from the `rag-implementation` skill:

  1. Corpus with rich metadata (source, category, author, year, tags, priority)
  2. Chunking that preserves metadata
  3. Dense embeddings (feature-hashing vectors) + sparse BM25 index (hybrid)
  4. Metadata filtering with a flexible filter language
  5. Relevance ranking: hybrid score -> reranking -> MMR diversity
  6. Grounded answer generation with citations + confidence
  7. Evaluation metrics (Recall@k, MRR, groundedness)
"""

from __future__ import annotations

import argparse
import json
import math
import re
import sys
import unicodedata
from collections import Counter, defaultdict
from dataclasses import dataclass, field
from typing import Callable, Iterable, Iterator, Optional

# --------------------------------------------------------------------------- #
# 1. Text utilities                                                           #
# --------------------------------------------------------------------------- #

STOPWORDS = frozenset(
    """
    a an and are as at be but by for from has have how in is it its of on or
    that the this to was were what when where which who will with you your
    our their can could do does did not no yes so than then too very just
    about into over under again further once here there all any both each
    few more most other some such only own same s t don now
    """.split()
)


def normalize(text: str) -> str:
    text = unicodedata.normalize("NFKC", text or "")
    text = text.lower()
    text = re.sub(r"[^\w\s-]", " ", text, flags=re.UNICODE)
    text = re.sub(r"\s+", " ", text).strip()
    return text


def tokenize(text: str) -> list[str]:
    return [t for t in normalize(text).split() if t and t not in STOPWORDS]


def sentences(text: str) -> list[str]:
    parts = re.split(r"(?<=[.!?])\s+|\n+", (text or "").strip())
    return [p.strip() for p in parts if p.strip()]


def cosine(a: dict[str, float], b: dict[str, float]) -> float:
    """Cosine similarity over sparse dict vectors."""
    if not a or not b:
        return 0.0
    small, large = (a, b) if len(a) <= len(b) else (b, a)
    dot = sum(weight * large.get(term, 0.0) for term, weight in small.items())
    na = math.sqrt(sum(w * w for w in a.values()))
    nb = math.sqrt(sum(w * w for w in b.values()))
    if na == 0.0 or nb == 0.0:
        return 0.0
    return dot / (na * nb)


# --------------------------------------------------------------------------- #
# 2. Documents & chunking                                                     #
# --------------------------------------------------------------------------- #

@dataclass
class Chunk:
    """A retrieval unit: text + the metadata of its parent document."""
    chunk_id: str
    text: str
    metadata: dict = field(default_factory=dict)
    parent_id: str = ""
    chunk_index: int = 0


def chunk_text(
    text: str, chunk_size: int = 300, overlap: int = 50, min_chunk: int = 40
) -> list[str]:
    """Recursive-character splitting tuned to sentence boundaries."""
    if len(text) <= chunk_size:
        return [text] if text.strip() else []
    units = sentences(text)
    chunks: list[str] = []
    current: list[str] = []
    current_len = 0
    for unit in units:
        unit_len = len(unit)
        if unit_len > chunk_size:  # hard-split an oversized unit
            if current:
                chunks.append(" ".join(current))
                current, current_len = [], 0
            for i in range(0, unit_len, chunk_size - overlap):
                chunks.append(unit[i : i + chunk_size])
            continue
        if current and current_len + unit_len + 1 > chunk_size:
            chunks.append(" ".join(current))
            carry = []
            carry_len = 0
            for prev in reversed(current):  # overlap from the tail
                if carry_len + len(prev) + 1 > overlap:
                    break
                carry.insert(0, prev)
                carry_len += len(prev) + 1
            current, current_len = carry, carry_len
        current.append(unit)
        current_len += unit_len + 1
    if current and current_len >= min_chunk:
        chunks.append(" ".join(current))
    elif current:
        if chunks:
            chunks[-1] = chunks[-1] + " " + " ".join(current)
        else:
            chunks.append(" ".join(current))
    return [c for c in chunks if c.strip()]


# --------------------------------------------------------------------------- #
# 3. Dense + sparse indices                                                   #
# --------------------------------------------------------------------------- #

class HashingEmbedder:
    """Feature-hashing dense embedder (deterministic, dependency-free).

    Hash token + position-sensitive shingles into a fixed-dim vector and
    normalize. Used in place of a learned model (e.g. all-MiniLM-L6-v2) so the
    pipeline runs anywhere; the scoring layer is model-agnostic.
    """

    def __init__(self, dim: int = 512, seed: int = 42, ngram: int = 2):
        self.dim = dim
        self.seed = seed
        self.ngram = ngram

    def _hash(self, key: str) -> int:
        h = self.seed
        for ch in key:
            h = ((h << 5) - h + ord(ch)) & 0xFFFFFFFF
        return h

    def embed(self, text: str) -> dict[str, float]:
        toks = tokenize(text)
        vec: dict[str, float] = {}
        for i in range(len(toks)):
            window = toks[max(0, i - self.ngram + 1) : i + 1]
            for j in range(len(window)):
                key = f"n{j + 1}:{':'.join(window[j:])}"
                idx = self._hash(key) % self.dim
                sign = 1.0 if (self._hash(key + "|s") & 1) else -1.0
                vec[idx] = vec.get(idx, 0.0) + sign
        norm = math.sqrt(sum(w * w for w in vec.values())) or 1.0
        return {k: v / norm for k, v in vec.items()}


class BM25Index:
    """Sparse lexical index with BM25 scoring."""

    def __init__(self, k1: float = 1.5, b: float = 0.75):
        self.k1, self.b = k1, b
        self.docs: list[Chunk] = []
        self.postings: dict[str, dict[int, int]] = defaultdict(dict)
        self.doc_len: list[int] = []
        self.doc_freq: dict[str, int] = Counter()
        self.avgdl = 0.0
        self.N = 0

    def add(self, chunk: Chunk) -> None:
        idx = self.N
        self.docs.append(chunk)
        counts = Counter(tokenize(chunk.text))
        self.doc_len.append(sum(counts.values()))
        for term, cnt in counts.items():
            self.postings[term][idx] = cnt
        self.N += 1

    def finalize(self) -> None:
        self.avgdl = (sum(self.doc_len) / self.N) if self.N else 0.0
        for term, posting in self.postings.items():
            self.doc_freq[term] = len(posting)

    def idf(self, term: str) -> float:
        n = self.doc_freq.get(term, 0)
        if n == 0:
            return 0.0
        return math.log(1.0 + (self.N - n + 0.5) / (n + 0.5))

    def score(self, query_terms: list[str]) -> dict[int, float]:
        scores: dict[int, float] = defaultdict(float)
        seen = set()
        for term in query_terms:
            if term in seen:
                continue
            seen.add(term)
            idf = self.idf(term)
            if idf == 0.0:
                continue
            for doc_id, tf in self.postings.get(term, {}).items():
                dl = self.doc_len[doc_id]
                denom = tf + self.k1 * (1 - self.b + self.b * dl / (self.avgdl or 1.0))
                scores[doc_id] += idf * (tf * (self.k1 + 1.0)) / denom
        return scores


# --------------------------------------------------------------------------- #
# 4. Metadata filtering                                                       #
# --------------------------------------------------------------------------- #

OPS = {
    "eq": lambda v, x: v == x,
    "ne": lambda v, x: v != x,
    "lt": lambda v, x: _cmp(v, x) < 0,
    "lte": lambda v, x: _cmp(v, x) <= 0,
    "gt": lambda v, x: _cmp(v, x) > 0,
    "gte": lambda v, x: _cmp(v, x) >= 0,
    "in": lambda v, x: v in x,
    "nin": lambda v, x: v not in x,
    "contains": lambda v, x: isinstance(v, str) and x.lower() in v.lower(),
    "icontains": lambda v, x: isinstance(v, str) and x.lower() in v.lower(),
    "startswith": lambda v, x: isinstance(v, str) and v.lower().startswith(x.lower()),
    "endswith": lambda v, x: isinstance(v, str) and v.lower().endswith(x.lower()),
    "any": lambda v, x: any(tag == x for tag in (v if isinstance(v, list) else [v])),
    "all": lambda v, x: all(tag in v for tag in x) if isinstance(v, list) else False,
    "has": lambda v, x: x in v if isinstance(v, (list, str, tuple, set)) else False,
    "exists": lambda v, x: v is not None,
}


def _cmp(a, b) -> int:
    try:
        return (a > b) - (a < b)
    except TypeError:  # mixed types -> compare string forms
        return (str(a) > str(b)) - (str(a) < str(b))


def _match(operator: str, value, expected) -> bool:
    op = OPS.get(operator.lower())
    if op is None:
        raise ValueError(f"Unknown metadata operator: {operator!r}")
    return op(value, expected)


def build_predicate(filters: Optional[dict]) -> Callable[[dict], bool]:
    """Compile a filter spec into a predicate over a metadata dict.

    Accepted shapes (AND-combined at the top level):
      {"key": "value"}                      -> eq
      {"key": {"$in": [...]}}               -> named operators ($eq, $gt, $in,
      {"key": {"$gte": ..., "$lte": ...}}   ->  $contains, $has, $any, ...)
      {"$or": [filter, ...], "$and": [...]} -> logical combinators
    """
    if not filters:
        return lambda meta: True

    def walk(spec) -> Callable[[dict], bool]:
        if isinstance(spec, dict) and "$or" in spec:
            subs = [walk(s) for s in spec["$or"]]
            return lambda meta: any(fn(meta) for fn in subs)
        if isinstance(spec, dict) and "$and" in spec:
            subs = [walk(s) for s in spec["$and"]]
            return lambda meta: all(fn(meta) for fn in subs)
        if isinstance(spec, dict) and "$not" in spec:
            sub = walk(spec["$not"])
            return lambda meta: not sub(meta)
        if not isinstance(spec, dict):
            raise ValueError("Filter spec must be a dict")
        parts: list[Callable[[dict], bool]] = []
        for key, cond in spec.items():
            if key in ("$or", "$and", "$not"):
                continue
            if isinstance(cond, dict) and all(
                k.startswith("$") for k in cond.keys()
            ):
                for op, expected in cond.items():
                    op_name = op.lstrip("$")
                    parts.append(
                        lambda meta, k=key, o=op_name, e=expected: _match(
                            o, meta.get(k), e
                        )
                    )
            else:
                parts.append(
                    lambda meta, k=key, e=cond: _match("eq", meta.get(k), e)
                )
        return lambda meta: all(fn(meta) for fn in parts)

    return walk(filters)


# --------------------------------------------------------------------------- #
# 5. Retriever: filter + hybrid ranking + rerank + MMR                        #
# --------------------------------------------------------------------------- #

@dataclass
class Hit:
    chunk: Chunk
    score: float
    dense: float = 0.0
    sparse: float = 0.0
    rerank: float = 0.0
    rank: int = 0

    def as_dict(self) -> dict:
        return {
            "chunk_id": self.chunk.chunk_id,
            "parent_id": self.chunk.parent_id,
            "text": self.chunk.text,
            "metadata": self.chunk.metadata,
            "score": round(self.score, 4),
            "dense": round(self.dense, 4),
            "sparse": round(self.sparse, 4),
            "rerank": round(self.rerank, 4),
            "rank": self.rank,
        }


class MetadataAwareRetriever:
    def __init__(
        self,
        embedder: Optional[HashingEmbedder] = None,
        dense_weight: float = 0.6,
        sparse_weight: float = 0.4,
        rerank_weight: float = 0.35,
    ):
        self.embedder = embedder or HashingEmbedder()
        self.dense_weight = dense_weight
        self.sparse_weight = sparse_weight
        self.rerank_weight = rerank_weight
        self.chunks: list[Chunk] = []
        self.dense_vectors: list[dict[str, float]] = []
        self.bm25 = BM25Index()
        self._by_parent: dict[str, list[int]] = defaultdict(list)

    # -- indexing ---------------------------------------------------------- #
    def add_document(self, doc_id: str, text: str, metadata: dict,
                     chunk_size: int = 300, overlap: int = 50) -> int:
        pieces = chunk_text(text, chunk_size=chunk_size, overlap=overlap)
        for i, piece in enumerate(pieces):
            chunk = Chunk(
                chunk_id=f"{doc_id}#{i}",
                text=piece,
                metadata=dict(metadata or {}),
                parent_id=doc_id,
                chunk_index=i,
            )
            self.add_chunk(chunk)
        return len(pieces)

    def add_chunk(self, chunk: Chunk) -> None:
        idx = len(self.chunks)
        self.chunks.append(chunk)
        self.dense_vectors.append(self.embedder.embed(chunk.text))
        self.bm25.add(chunk)
        self._by_parent[chunk.parent_id].append(idx)

    def finalize(self) -> None:
        self.bm25.finalize()

    def index_corpus(
        self, documents: Iterable[tuple[str, str, dict]], **kwargs
    ) -> int:
        total = 0
        for doc_id, text, metadata in documents:
            total += self.add_document(doc_id, text, metadata, **kwargs)
        self.finalize()
        return total

    # -- scoring ------------------------------------------------------------ #
    def _query_vector(self, query: str) -> dict[str, float]:
        return self.embedder.embed(query)

    def _dense_scores(self, query: str) -> dict[int, float]:
        qv = self._query_vector(query)
        return {
            i: cosine(qv, vec) for i, vec in enumerate(self.dense_vectors)
        }

    def _sparse_scores(self, query: str) -> dict[int, float]:
        return self.bm25.score(tokenize(query))

    @staticmethod
    def _normalize(scores: dict[int, float]) -> dict[int, float]:
        if not scores:
            return {}
        mx = max(scores.values())
        if mx <= 0.0:
            return {}
        return {i: s / mx for i, s in scores.items()}

    # -- retrieval ---------------------------------------------------------- #
    def search(
        self,
        query: str,
        filters: Optional[dict] = None,
        top_k: int = 5,
        candidates: int = 30,
        use_mmr: bool = False,
        mmr_lambda: float = 0.7,
        rerank: bool = True,
    ) -> list[Hit]:
        predicate = build_predicate(filters)
        dense = self._normalize(self._dense_scores(query))
        sparse = self._normalize(self._sparse_scores(query))

        # Candidate set: union of both scorers, restricted to filter pass.
        candidates_ids = set(dense) | set(sparse)
        if len(candidates_ids) < top_k:  # metadata may hide everything else
            candidates_ids = set(range(len(self.chunks)))
        cands = [
            i
            for i in candidates_ids
            if predicate(self.chunks[i].metadata)
        ]
        if not cands:
            return []

        hybrid: dict[int, float] = {}
        for i in cands:
            d = dense.get(i, 0.0)
            s = sparse.get(i, 0.0)
            if d == 0.0 and s == 0.0:
                continue
            hybrid[i] = self.dense_weight * d + self.sparse_weight * s

        ranked = sorted(hybrid.items(), key=lambda kv: kv[1], reverse=True)
        top = ranked[: candidates]

        # Reranking: emphasize term-overlap + metadata priors.
        if rerank and top:
            qterms = set(tokenize(query))
            top = sorted(
                top,
                key=lambda kv: (
                    kv[1]
                    + self.rerank_weight * self._rerank_score(
                        self.chunks[kv[0]], qterms, filters
                    )
                ),
                reverse=True,
            )

        if use_mmr:
            top = self._mmr_select(top, mmr_lambda, top_k)

        hits = []
        for rank, (idx, score) in enumerate(top[:top_k], start=1):
            hits.append(
                Hit(
                    chunk=self.chunks[idx],
                    score=score,
                    dense=dense.get(idx, 0.0),
                    sparse=sparse.get(idx, 0.0),
                    rank=rank,
                )
            )
        return hits

    def _rerank_score(self, chunk: Chunk, qterms: set[str],
                      filters: Optional[dict]) -> float:
        """Contextual signal: lexical overlap + metadata-query affinity."""
        terms = set(tokenize(chunk.text))
        overlap = len(qterms & terms)
        lexical = overlap / max(len(qterms), 1)
        meta_signal = 0.0
        meta = chunk.metadata
        for term in qterms:
            for value in meta.values():
                if isinstance(value, str) and term in value.lower():
                    meta_signal += 0.05
                elif isinstance(value, list) and any(
                    term in str(v).lower() for v in value
                ):
                    meta_signal += 0.05
        return lexical + min(meta_signal, 0.3)

    def _mmr_select(self, ranked: list[tuple[int, float]], lam: float,
                    top_k: int) -> list[tuple[int, float]]:
        """Maximal Marginal Relevance: relevance + diversity."""
        if len(ranked) <= top_k:
            return ranked
        selected: list[int] = []
        pool = list(ranked)
        while selected and len(selected) < top_k:
            pass  # placeholder for clarity; full loop below
        selected = []
        while len(selected) < top_k:
            best = None
            best_val = -1.0
            for idx, score in pool:
                if idx in selected:
                    continue
                max_sim = 0.0
                for s_idx in selected:
                    sim = cosine(
                        self.dense_vectors[idx], self.dense_vectors[s_idx]
                    )
                    max_sim = max(max_sim, sim)
                val = lam * score - (1 - lam) * max_sim
                if val > best_val:
                    best_val = val
                    best = (idx, score)
            if best is None:
                break
            selected.append(best[0])
        order = [i for i, _ in ranked]
        chosen = sorted(selected, key=order.index)
        return [(i, dict(ranked)[i]) for i in chosen]


# --------------------------------------------------------------------------- #
# 6. Grounded answer generation (no external LLM required)                    #
# --------------------------------------------------------------------------- #

class GroundedResponder:
    """Extractive grounded responder with citations and confidence.

    Replaces the LLM step with a deterministic, verifiable summarizer so the
    pipeline is fully self-contained; the retrieval/ranking layer is the
    component under test.
    """

    def answer(self, query: str, hits: list[Hit]) -> dict:
        if not hits:
            return {
                "answer": "I don't have enough information to answer this question.",
                "confidence": 0.0,
                "citations": [],
            }
        qterms = set(tokenize(query))
        evidence: list[tuple[str, str]] = []
        for hit in hits[:3]:
            for sent in sentences(hit.chunk.text):
                sterms = set(tokenize(sent))
                if sterms and qterms & sterms:
                    evidence.append((sent, hit.chunk.chunk_id))
        if not evidence:
            best = hits[0].chunk.text[:280]
            evidence = [(best, hits[0].chunk.chunk_id)]

        seen, chosen = set(), []
        for sent, cid in evidence:
            key = normalize(sent)
            if key in seen or len(sent) > 320:
                continue
            seen.add(key)
            chosen.append((sent, cid))
            if len(chosen) == 3:
                break

        answer = " ".join(s for s, _ in chosen)
        citations = [f"[{i + 1}] {cid}" for i, (_, cid) in enumerate(chosen)]
        max_score = max(h.score for h in hits[:3]) if hits else 0.0
        grounded = sum(
            1 for s, _ in chosen if qterms & set(tokenize(s))
        ) / max(len(chosen), 1)
        confidence = round(0.35 * max_score + 0.65 * grounded, 3)
        return {
            "answer": answer,
            "confidence": confidence,
            "citations": citations,
        }


# --------------------------------------------------------------------------- #
# 7. The RAG system facade                                                    #
# --------------------------------------------------------------------------- #

class MetadataRAG:
    def __init__(self, retriever: Optional[MetadataAwareRetriever] = None,
                 responder: Optional[GroundedResponder] = None):
        self.retriever = retriever or MetadataAwareRetriever()
        self.responder = responder or GroundedResponder()
        self.statistics = {"chunks": 0, "documents": 0}

    def add_document(self, doc_id, text, metadata, **kw) -> int:
        n = self.retriever.add_document(doc_id, text, metadata, **kw)
        self.statistics["documents"] += 1
        self.statistics["chunks"] += n
        return n

    def finalize(self) -> None:
        self.retriever.finalize()

    def query(
        self,
        query: str,
        filters: Optional[dict] = None,
        top_k: int = 5,
        use_mmr: bool = False,
        mmr_lambda: float = 0.7,
        rerank: bool = True,
    ) -> dict:
        hits = self.retriever.search(
            query,
            filters=filters,
            top_k=top_k,
            use_mmr=use_mmr,
            mmr_lambda=mmr_lambda,
            rerank=rerank,
        )
        result = self.responder.answer(query, hits)
        result["query"] = query
        result["filters"] = filters or {}
        result["results"] = [h.as_dict() for h in hits]
        return result

    def save_index(self, path: str) -> None:
        payload = {
            "chunks": [
                {"chunk_id": c.chunk_id, "text": c.text,
                 "metadata": c.metadata, "parent_id": c.parent_id}
                for c in self.retriever.chunks
            ]
        }
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, ensure_ascii=False, indent=2)

    def load_index(self, path: str) -> None:
        with open(path, encoding="utf-8") as fh:
            payload = json.load(fh)
        for c in payload["chunks"]:
            self.retriever.add_chunk(
                Chunk(c["chunk_id"], c["text"], c["metadata"], c["parent_id"])
            )
        self.retriever.finalize()
        self.statistics["chunks"] = len(self.retriever.chunks)


