def evaluate(rag: MetadataRAG, cases: list[dict]) -> dict:
    """Compute Recall@k, MRR and groundedness over labelled test cases."""
    r_at_k, mrr, grounded = [], [], []
    for case in cases:
        query = case["query"]
        expected = set(case["relevant"])
        filters = case.get("filters")
        result = rag.query(query, filters=filters, top_k=case.get("k", 5))
        retrieved = [h.chunk.parent_id for h in result["results"]]
        hits = set(retrieved)
        if expected:
            rel = len(expected & hits)
            r_at_k.append(rel / len(expected))
            for i, parent in enumerate(retrieved, start=1):
                if parent in expected:
                    mrr.append(1.0 / i)
                    break
            else:
                mrr.append(0.0)
        grounded.append(result["confidence"] > 0.0)
    return {
        "recall@k": round(sum(r_at_k) / len(r_at_k), 3) if r_at_k else 0.0,
        "mrr": round(sum(mrr) / len(mrr), 3) if mrr else 0.0,
        "grounded_ratio": round(sum(grounded) / len(grounded), 3) if grounded else 0.0,
        "cases": len(cases),
    }


