# 9. Demo                                                                     #
# --------------------------------------------------------------------------- #

def run_demo() -> None:
    rag = MetadataRAG()
    docs = demo_corpus()
    for doc_id, text, meta in docs:
        rag.add_document(doc_id, text, meta)
    rag.finalize()

    print("=" * 72)
    print("METADATA-AWARE RAG SYSTEM — DEMO")
    print(f"Indexed {rag.statistics['documents']} documents, "
          f"{rag.statistics['chunks']} chunks (metadata preserved).")
    print("=" * 72)

    queries = [
        {
            "label": "Unfiltered query (relevance ranking only)",
            "query": "How does hybrid retrieval reduce hallucinations?",
        },
        {
            "label": "Metadata filter: only security docs",
            "query": "What verifies identity at every request?",
            "filters": {"category": "security"},
        },
        {
            "label": "Metadata filter: year >= 2022 AND priority high",
            "query": "How does reranking improve retrieval?",
            "filters": {"year": {"$gte": 2022}, "priority": "high"},
        },
        {
            "label": "Metadata filter: tags contain 'metadata' OR source is ops",
            "query": "Which documents talk about metadata filtering?",
            "filters": {
                "$or": [
                    {"tags": {"$has": "metadata"}},
                    {"source": {"$endswith": "runbook.md"}},
                ]
            },
        },
        {
            "label": "Filtered + MMR diversity",
            "query": "retrieval quality and ranking",
            "filters": {"category": "machine-learning"},
            "use_mmr": True,
        },
        {
            "label": "Filter excludes everything (no candidates)",
            "query": "vector databases",
            "filters": {"year": {"$lt": 2000}},
        },
    ]

    for spec in queries:
        print("\n" + "-" * 72)
        print(f"Q: {spec['query']}")
        print(f"  [{spec['label']}]")
        if spec.get("filters"):
            print(f"  filters = {json.dumps(spec['filters'], ensure_ascii=False)}")
        result = rag.query(
            spec["query"],
            filters=spec.get("filters"),
            use_mmr=spec.get("use_mmr", False),
        )
        if result["results"]:
            print(f"  ANSWER (confidence {result['confidence']}): "
                  f"{result['answer']}")
            print(f"  CITATIONS: {', '.join(result['citations'])}")
            for hit in result["results"]:
                meta = hit["metadata"]
                print(f"    rank {hit['rank']}: {hit['parent_id']} "
                      f"(score={hit['score']}, dense={hit['dense']}, "
                      f"sparse={hit['sparse']}) "
                      f"category={meta.get('category')} year={meta.get('year')} "
                      f"priority={meta.get('priority')}")
        else:
            print("  ANSWER: No documents match the query + metadata filters.")
            print("  (Filtering correctly pruned the candidate set.)")

    print("\n" + "=" * 72)
    print("EVALUATION")
    cases = [
        {"query": "zero trust identity verification", "relevant": {"doc-security-2021", "doc-security-2023"}},
        {"query": "reranking and MMR improve retrieval", "relevant": {"doc-ml-2024", "doc-ml-2022"}},
        {"query": "vector database similarity search", "relevant": {"doc-db-2020"}},
        {"query": "production monitoring of rag systems", "relevant": {"doc-ops-2023"}},
        {"query": "identity access", "relevant": {"doc-security-2021", "doc-security-2023"},
         "filters": {"category": "security"}},
        {"query": "how to filter by metadata before ranking", "relevant": {"doc-ml-2024"},
         "filters": {"tags": {"$has": "filtering"}}},
    ]
    metrics = evaluate(rag, cases)
    print(json.dumps(metrics, indent=2))

    # Persistence round-trip check
    rag.save_index("metadata_rag_index.json")
    clone = MetadataRAG()
    clone.load_index("metadata_rag_index.json")
    assert clone.statistics["chunks"] == rag.statistics["chunks"], "index reload mismatch"
    a = rag.query("hybrid retrieval")
    b = clone.query("hybrid retrieval")
    assert [h.chunk.chunk_id for h in a["results"]] == [
        h.chunk.chunk_id for h in b["results"]
    ], "index reload changed results"
    print("\nIndex persistence round-trip: OK "
          f"({clone.statistics['chunks']} chunks reloaded)")


def main(argv: Optional[list[str]] = None) -> int:
    parser = argparse.ArgumentParser(description="Metadata-aware RAG system")
    parser.add_argument("--demo", action="store_true", default=True,
                        help="run the demo (default)")
    args = parser.parse_args(argv)
    if args.demo:
        run_demo()
    return 0


if __name__ == "__main__":
    sys.exit(main())
